import { fetch } from 'wix-fetch';
import { getSecret } from 'wix-secrets-backend';
// Call only after the existing Sales staff and customer authorization.
export async function requestMasterFulfilment({company,customerId,customerName,staff,action,requestId,input}){if(!['NCT','GHR'].includes(company)||!['READ','SELECT','CANCEL','DOCUMENT','PLAN','ORDER_DATE','ADJUST','CHAT_LIST','CHAT_PAGE','CHAT_SAVE'].includes(action))throw Error('Invalid shipment request.');const secret=await getSecret('MASTER_INTAKE_SHARED_SECRET');if(!secret)throw Error('Master connection is not configured.');const reply=await fetch('https://fmcg999.wixstudio.com/master/_functions/r2SalesFulfilment',{method:'post',headers:{'Content-Type':'application/json', 'X-FMCG-Cohort': 'MASTER_20261024_R2',Authorization:'Bearer '+secret},body:JSON.stringify({company,customerId,customerName,staff:{staffId:staff.staffId,staffName:staff.staffName},action,requestId,input})});const value=await reply.json();if(!reply.ok||value.ok!==true)throw Error(value.error||'Shipment request could not be confirmed.');return value.result;}
